-- Lesson: deriving-quadratic-formula
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_cddd3ed114a715', 'deriving-quadratic-formula', 'Deriving the quadratic formula', 'Derive the quadratic formula by completing the square on ax² + bx + c = 0, see where the discriminant comes from, and connect the formula to the axis of symmetry.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a4b179629e7ed1', 'les_cddd3ed114a715', 1, 'Complete the square on the general equation ax² + bx + c = 0 to derive the quadratic formula.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0302ce5f64d284', 'les_cddd3ed114a715', 2, 'Explain the role of the discriminant b² − 4ac in the derivation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f32e4e7b54a552', 'les_cddd3ed114a715', 3, 'Connect −b/(2a) in the formula to the axis of symmetry and the symmetry of the roots.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a4b179629e7ed1', 'les_cddd3ed114a715', 'learn', 1, 'text', '{"body":"Completing the square solves any particular quadratic. Doing it once with letters instead of numbers solves every quadratic at once. The result is the quadratic formula."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0302ce5f64d284', 'les_cddd3ed114a715', 'learn', 2, 'worked_example', '{"title":"Derive the solutions of $ax^2 + bx + c = 0$, $a \\ne 0$","steps":[{"latex":"x^2 + \\tfrac{b}{a}x + \\tfrac{c}{a} = 0","explanation":"Divide every term by a so the leading coefficient is 1."},{"latex":"x^2 + \\tfrac{b}{a}x = -\\tfrac{c}{a}","explanation":"Move the constant to the right."},{"latex":"x^2 + \\tfrac{b}{a}x + \\tfrac{b^2}{4a^2} = \\tfrac{b^2}{4a^2} - \\tfrac{c}{a}","explanation":"Add $\\left(\\frac{b}{2a}\\right)^2 = \\frac{b^2}{4a^2}$ to both sides."},{"latex":"\\left(x + \\tfrac{b}{2a}\\right)^2 = \\tfrac{b^2 - 4ac}{4a^2}","explanation":"Factor the left; write the right over the common denominator $4a^2$."},{"latex":"x + \\tfrac{b}{2a} = \\pm\\tfrac{\\sqrt{b^2 - 4ac}}{2a}","explanation":"Take square roots. $\\sqrt{4a^2} = 2|a|$, and the $\\pm$ covers either sign of $a$."},{"latex":"x = \\dfrac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}","explanation":"Subtract $\\frac{b}{2a}$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f32e4e7b54a552', 'les_cddd3ed114a715', 'learn', 3, 'text', '{"body":"The step before taking square roots explains the discriminant. The left side is a square, so it can''t be negative. If $b^2 - 4ac < 0$, the right side is negative and there is no real solution. If it equals 0, there is exactly one solution, $x = -\\frac{b}{2a}$. If it is positive, there are two."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6306a8eaef0246', 'les_cddd3ed114a715', 'learn', 4, 'text', '{"body":"The formula also shows symmetry: both roots are the same distance, $\\frac{\\sqrt{b^2 - 4ac}}{2|a|}$, from $-\\frac{b}{2a}$, which is exactly the axis of symmetry. The average of the roots is always $-\\frac{b}{2a}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5c975a1ecffecd', 'les_cddd3ed114a715', 'learn', 5, 'worked_example', '{"title":"Use the formula on $2x^2 + 3x - 5 = 0$ and compare with factoring","steps":[{"latex":"x = \\frac{-3 \\pm \\sqrt{9 + 40}}{4} = \\frac{-3 \\pm 7}{4}","explanation":"a = 2, b = 3, c = −5."},{"latex":"x = 1 \\text{ or } x = -\\tfrac{5}{2}","explanation":""},{"latex":"(2x + 5)(x - 1) = 0","explanation":"Factoring gives the same roots."}],"check":"The axis of symmetry is $x = -\\frac{3}{4}$, and $\\frac{1 + (-2.5)}{2} = -0.75$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_002996edb52d6e', 'les_cddd3ed114a715', 'learn', 6, 'callout', '{"tone":"warning","title":"The fraction bar covers everything","body":"The $2a$ divides both $-b$ and the square root. Writing $-b \\pm \\frac{\\sqrt{b^2 - 4ac}}{2a}$ is a common error."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_56a5dec0fe242d', 'les_cddd3ed114a715', 'learn', 7, 'callout', '{"tone":"note","title":"Vieta''s formulas","body":"Adding and multiplying the two roots from the formula gives $x_1 + x_2 = -\\frac{b}{a}$ and $x_1 x_2 = \\frac{c}{a}$. These are quick checks on any answer."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fe00c333787060', 'les_cddd3ed114a715', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every time software solves a quadratic, for projectile timing, optimization or graphics, it uses this formula (often in a rearranged form that avoids rounding error)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a4b179629e7ed1', 'les_cddd3ed114a715', 1, 'practice', 'multiple_choice', 1, 'In the derivation, what is added to both sides to complete the square on $x^2 + \frac{b}{a}x$?', '{"choices":["$\\frac{b}{2a}$","$\\frac{b^2}{4a^2}$","$\\frac{b^2}{4a}$","$\\frac{b^2}{a^2}$"],"answer":1}', '["Half of $\\frac{b}{a}$, squared."]', '$\left(\frac{b}{2a}\right)^2 = \frac{b^2}{4a^2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0302ce5f64d284', 'les_cddd3ed114a715', 2, 'practice', 'multiple_choice', 2, 'Why does a negative discriminant mean no real solutions?', '{"choices":["The formula divides by zero","A square can''t equal a negative number","a must be negative","The roots would be equal"],"answer":1}', '["Look at $\\left(x + \\frac{b}{2a}\\right)^2 = \\frac{b^2 - 4ac}{4a^2}$."]', 'The left side is a square of a real number, so it is at least 0. It can''t equal a negative right side.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f32e4e7b54a552', 'les_cddd3ed114a715', 3, 'practice', 'numeric', 2, 'What is the sum of the roots of $3x^2 - 12x + 5 = 0$?', '{"answer":4}', '["Sum $= -\\frac{b}{a}$."]', '$-\frac{-12}{3} = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6306a8eaef0246', 'les_cddd3ed114a715', 4, 'practice', 'numeric', 2, 'What is the product of the roots of $3x^2 - 12x + 5 = 0$? Enter a fraction or decimal.', '{"answer":1.6666666666666667,"tolerance":0.000001}', '["Product $= \\frac{c}{a}$."]', '$\frac{5}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5c975a1ecffecd', 'les_cddd3ed114a715', 5, 'practice', 'short_text', 3, 'Use the formula to solve $x^2 - 6x + 4 = 0$. Enter the solutions in the form a±sqrt(b), like 3±sqrt(5).', '{"accept":["3±sqrt(5)","3±√5","3+-sqrt(5)","3±sqrt5"]}', '["$\\frac{6 \\pm \\sqrt{36 - 16}}{2} = \\frac{6 \\pm \\sqrt{20}}{2}$.","$\\sqrt{20} = 2\\sqrt{5}$."]', '$x = 3 \pm \sqrt{5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_002996edb52d6e', 'les_cddd3ed114a715', 6, 'review', 'numeric', 3, 'The roots of a quadratic are 2 and 8. What is the axis of symmetry? Enter the x-value.', '{"answer":5}', '["The axis is halfway between the roots."]', '$\frac{2 + 8}{2} = 5$, which equals $-\frac{b}{2a}$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cddd3ed114a715', (SELECT id FROM concepts WHERE slug = 'completing-the-square'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3a01f099257681', 'subj_math', 'discriminant', 'Discriminant', 'b² − 4ac, which tells how many real solutions a quadratic equation has.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cddd3ed114a715', (SELECT id FROM concepts WHERE slug = 'discriminant'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_cddd3ed114a715', (SELECT id FROM formulas WHERE slug = 'quadratic-formula'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_cddd3ed114a715', (SELECT id FROM formulas WHERE slug = 'discriminant'), 2);

-- Lesson: geometric-sequences
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f148baa4cbc7ce', 'geometric-sequences', 'Geometric sequences and recursive rules', 'Identify geometric sequences, write explicit and recursive rules, and connect them to exponential functions with whole-number inputs.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2b66e72f6384f4', 'les_f148baa4cbc7ce', 1, 'Identify a geometric sequence and its common ratio.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7c97eee931d093', 'les_f148baa4cbc7ce', 2, 'Write explicit and recursive rules for arithmetic and geometric sequences and translate between them.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_72a92e060824d3', 'les_f148baa4cbc7ce', 3, 'Relate geometric sequences to exponential functions and solve applied problems.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b66e72f6384f4', 'les_f148baa4cbc7ce', 'learn', 1, 'definition', '{"term":"Geometric sequence","body":"A sequence in which each term after the first is found by multiplying the previous term by the same nonzero number $r$, the common ratio. Example: 3, 6, 12, 24, … has $r = 2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c97eee931d093', 'les_f148baa4cbc7ce', 'learn', 2, 'formula', '{"latex":"a_n = a_1 \\cdot r^{\\,n-1}","title":"Explicit rule","note":"Start at $a_1$ and multiply by $r$ a total of $n - 1$ times."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_72a92e060824d3', 'les_f148baa4cbc7ce', 'learn', 3, 'definition', '{"term":"Recursive rule","body":"Geometric: $a_1$ given and $a_n = r \\cdot a_{n-1}$. Arithmetic: $a_1$ given and $a_n = a_{n-1} + d$. A recursive rule always needs a starting term."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_affd833be86ff4', 'les_f148baa4cbc7ce', 'learn', 4, 'worked_example', '{"title":"Find the 8th term of 80, 40, 20, 10, …","steps":[{"latex":"r = \\tfrac{40}{80} = \\tfrac{1}{2}","explanation":"Divide any term by the one before."},{"latex":"a_8 = 80 \\cdot \\left(\\tfrac{1}{2}\\right)^7 = \\tfrac{80}{128} = 0.625","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_39030e8c34a7bb', 'les_f148baa4cbc7ce', 'learn', 5, 'worked_example', '{"title":"A geometric sequence has $a_2 = 12$ and $a_5 = 324$. Find $a_1$ and $r$.","steps":[{"latex":"a_5 = a_2 \\cdot r^3 \\Rightarrow 324 = 12r^3","explanation":"Three steps from term 2 to term 5."},{"latex":"r^3 = 27 \\Rightarrow r = 3","explanation":""},{"latex":"a_1 = 12 \\div 3 = 4","explanation":"So $a_n = 4 \\cdot 3^{n-1}$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b8b73cf1fd5675', 'les_f148baa4cbc7ce', 'learn', 6, 'text', '{"body":"A geometric sequence is an exponential function restricted to whole-number inputs: $a_n = 4 \\cdot 3^{n-1}$ matches $f(x) = \\frac{4}{3} \\cdot 3^x$ at $x = 1, 2, 3, \\dots$ Its points lie on an exponential curve, just as an arithmetic sequence''s points lie on a line."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_86e6f4110e205f', 'les_f148baa4cbc7ce', 'experiment', 7, 'activity', '{"activity":"growth-models","title":"Arithmetic vs geometric","params":{"a":4,"b":2,"d":4,"compare":true}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bad31351714db6', 'les_f148baa4cbc7ce', 'experiment', 8, 'callout', '{"tone":"tip","title":"Try this","body":"The dots on the exponential curve are the terms 4, 8, 16, 32, … (starting from $x = 0$). The line adds 4 each step: 4, 8, 12, 16, … They agree for two terms and then separate. Try a ratio below 1 to see a decreasing geometric sequence."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_89aa9b5f55a3fe', 'les_f148baa4cbc7ce', 'learn', 9, 'callout', '{"tone":"warning","title":"Negative and fractional ratios","body":"With $r = -2$, the terms alternate signs: 3, −6, 12, −24, … With $0 < r < 1$, they shrink toward 0 but never reach it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c7a2ad0e33da2', 'les_f148baa4cbc7ce', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"A ball rebounding to 60% of its previous height, a population growing 5% a year, and the number of people reached when each person tells 3 more all form geometric sequences."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b66e72f6384f4', 'les_f148baa4cbc7ce', 1, 'practice', 'numeric', 1, 'What is the common ratio of 5, −15, 45, −135, …?', '{"answer":-3}', '["Divide a term by the previous term."]', '$-15 \div 5 = -3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c97eee931d093', 'les_f148baa4cbc7ce', 2, 'practice', 'numeric', 1, 'Find the next term of 2, 8, 32, …', '{"answer":128}', '["Multiply by 4."]', '$32 \cdot 4 = 128$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_72a92e060824d3', 'les_f148baa4cbc7ce', 3, 'practice', 'numeric', 2, 'Find $a_6$ for $a_n = 3 \cdot 2^{n-1}$.', '{"answer":96}', '["$3 \\cdot 2^5$."]', '$3 \cdot 32 = 96$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_affd833be86ff4', 'les_f148baa4cbc7ce', 4, 'practice', 'short_text', 2, 'Write a recursive rule for 7, 21, 63, … in the form a_n=…a_(n-1).', '{"accept":["a_n=3a_(n-1)","a_n=3*a_(n-1)","an=3a(n-1)"]}', '["What do you multiply by each time?"]', '$a_1 = 7$ and $a_n = 3a_{n-1}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_39030e8c34a7bb', 'les_f148baa4cbc7ce', 5, 'practice', 'multiple_choice', 2, 'Which sequence is geometric?', '{"choices":["2, 4, 6, 8, …","1, 4, 9, 16, …","81, 27, 9, 3, …","10, 7, 4, 1, …"],"answer":2}', '["Check for a constant ratio."]', '81, 27, 9, 3 has ratio $\frac{1}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b8b73cf1fd5675', 'les_f148baa4cbc7ce', 6, 'practice', 'numeric', 3, 'A ball is dropped from 10 m and each bounce reaches 60% of the previous height. How high does it go after the 4th bounce? Round to the nearest hundredth.', '{"answer":1.3,"unit":"m","tolerance":0.006}', '["$10 \\cdot 0.6^4$."]', '$10 \cdot 0.1296 = 1.296 \approx 1.30$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_86e6f4110e205f', 'les_f148baa4cbc7ce', 7, 'review', 'numeric', 3, 'In a geometric sequence, $a_1 = 2$ and $a_4 = 54$. Find $a_7$.', '{"answer":1458}', '["$r^3 = 27$, so $r = 3$."]', '$a_7 = 2 \cdot 3^6 = 2 \cdot 729 = 1458$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_f148baa4cbc7ce', 'subj_math', 'geometric-sequences', 'Geometric sequences', 'Sequences with a constant ratio between consecutive terms.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f148baa4cbc7ce', (SELECT id FROM concepts WHERE slug = 'geometric-sequences'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f148baa4cbc7ce', (SELECT id FROM concepts WHERE slug = 'arithmetic-sequences'));
