-- Lesson: linear-quadratic-systems
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8c36ed64305efe', 'linear-quadratic-systems', 'Linear-quadratic systems', 'Solve systems with one line and one parabola by substitution and by graphing, and use the discriminant to predict zero, one or two intersection points.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_90f6416e08edf9', 'les_8c36ed64305efe', 1, 'Solve a linear-quadratic system by substitution, finding both coordinates of each solution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_64f7393406e179', 'les_8c36ed64305efe', 2, 'Explain graphically why such a system can have zero, one or two solutions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_98cfef2775c90c', 'les_8c36ed64305efe', 3, 'Use the discriminant of the resulting quadratic to count solutions without solving.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90f6416e08edf9', 'les_8c36ed64305efe', 'learn', 1, 'text', '{"body":"A line can miss a parabola, touch it at exactly one point (a tangent line), or cross it twice. So a system of one linear and one quadratic equation has zero, one or two real solutions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_64f7393406e179', 'les_8c36ed64305efe', 'learn', 2, 'worked_example', '{"title":"Solve $y = x^2 - 2x - 3$ and $y = x + 1$","steps":[{"latex":"x^2 - 2x - 3 = x + 1","explanation":"Both equal y, so set them equal."},{"latex":"x^2 - 3x - 4 = 0 \\Rightarrow (x - 4)(x + 1) = 0","explanation":""},{"latex":"x = 4 \\Rightarrow y = 5;\\quad x = -1 \\Rightarrow y = 0","explanation":"Find y from the linear equation."},{"latex":"(4, 5) \\text{ and } (-1, 0)","explanation":""}],"check":"Check $(4, 5)$ in the parabola: $16 - 8 - 3 = 5$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_98cfef2775c90c', 'les_8c36ed64305efe', 'experiment', 3, 'activity', '{"activity":"vertex-explorer","title":"Imagine a line across this parabola","params":{"a":1,"h":1,"k":-4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_58bc970195f281', 'les_8c36ed64305efe', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"This parabola is $y = (x - 1)^2 - 4 = x^2 - 2x - 3$, the one in the example. Picture the line $y = x + 1$ through $(-1, 0)$ and $(4, 5)$. Now picture $y = -5$: it misses entirely. Which horizontal line touches the parabola exactly once?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f264f0dcb8bcd3', 'les_8c36ed64305efe', 'learn', 5, 'worked_example', '{"title":"How many solutions does $y = x^2 + 4$, $y = 2x + 1$ have?","steps":[{"latex":"x^2 + 4 = 2x + 1 \\Rightarrow x^2 - 2x + 3 = 0","explanation":""},{"latex":"b^2 - 4ac = 4 - 12 = -8 < 0","explanation":"Negative discriminant."},{"latex":"\\text{No real solutions}","explanation":"The line passes below the parabola without touching it."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a8455f739193e2', 'les_8c36ed64305efe', 'learn', 6, 'worked_example', '{"title":"Find $k$ so that $y = kx$ is tangent to $y = x^2 + 1$ (for $k > 0$)","steps":[{"latex":"x^2 - kx + 1 = 0","explanation":"Set equal and rearrange."},{"latex":"k^2 - 4 = 0","explanation":"Tangent means exactly one solution: discriminant 0."},{"latex":"k = 2","explanation":"The line $y = 2x$ touches the parabola at $(1, 2)$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dbe48c1f86f0b2', 'les_8c36ed64305efe', 'learn', 7, 'callout', '{"tone":"warning","title":"Pair each x with its y","body":"Each x-value gives its own point. After finding $x = 4$ and $x = -1$, compute each $y$ separately. Use the linear equation; it''s easier and less error-prone."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1669cc8228bca3', 'les_8c36ed64305efe', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Does a thrown ball''s parabolic path clear a sloped roof? When does a car accelerating from rest (distance $\\frac{1}{2}at^2$) catch one moving at constant speed ($vt + d_0$)? Both are linear-quadratic systems."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90f6416e08edf9', 'les_8c36ed64305efe', 1, 'practice', 'short_text', 2, 'Solve $y = x^2$ and $y = 4$. Enter the two points as (x,y),(x,y), smaller x first.', '{"accept":["(-2,4),(2,4)"]}', '["$x^2 = 4$."]', '$x = \pm 2$: $(-2, 4)$ and $(2, 4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_64f7393406e179', 'les_8c36ed64305efe', 2, 'practice', 'short_text', 2, 'Solve $y = x^2 + 1$ and $y = x + 3$. Enter the points, smaller x first.', '{"accept":["(-1,2),(2,5)"]}', '["$x^2 - x - 2 = 0$."]', '$(x - 2)(x + 1) = 0$: $(2, 5)$ and $(-1, 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_98cfef2775c90c', 'les_8c36ed64305efe', 3, 'practice', 'multiple_choice', 2, 'How many solutions does $y = x^2 - 6x + 9$, $y = 0$ have?', '{"choices":["0","1","2","Infinitely many"],"answer":1}', '["$x^2 - 6x + 9 = (x - 3)^2$."]', 'The x-axis is tangent at $(3, 0)$: exactly one solution.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_58bc970195f281', 'les_8c36ed64305efe', 4, 'practice', 'multiple_choice', 2, 'How many solutions does $y = -x^2 + 2$, $y = x + 5$ have?', '{"choices":["0","1","2","3"],"answer":0}', '["$-x^2 + 2 = x + 5 \\Rightarrow x^2 + x + 3 = 0$.","Find the discriminant."]', '$1 - 12 = -11 < 0$, so no real solutions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f264f0dcb8bcd3', 'les_8c36ed64305efe', 5, 'practice', 'short_text', 3, 'For what positive value of $b$ is the line $y = 2x + b$ tangent to $y = x^2 + 3$?', '{"accept":["2","b=2"]}', '["$x^2 - 2x + (3 - b) = 0$.","Set the discriminant to 0."]', '$4 - 4(3 - b) = 0 \Rightarrow 4b = 8 \Rightarrow b = 2$. Tangent point $(1, 4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a8455f739193e2', 'les_8c36ed64305efe', 6, 'review', 'short_text', 3, 'Solve $y = x^2 - 4x + 5$ and $y = 2x - 3$. Enter the points, smaller x first.', '{"accept":["(2,1),(4,5)"]}', '["$x^2 - 6x + 8 = 0$."]', '$(x - 2)(x - 4) = 0$: $(2, 1)$ and $(4, 5)$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8c36ed64305efe', (SELECT id FROM concepts WHERE slug = 'systems-of-equations'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_3a01f099257681', 'subj_math', 'discriminant', 'Discriminant', 'b² − 4ac, which tells how many real solutions a quadratic equation has.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8c36ed64305efe', (SELECT id FROM concepts WHERE slug = 'discriminant'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_8c36ed64305efe', (SELECT id FROM formulas WHERE slug = 'quadratic-formula'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_8c36ed64305efe', (SELECT id FROM formulas WHERE slug = 'discriminant'), 2);

-- Lesson: operations-with-radicals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_00ede0b35eda6d', 'operations-with-radicals', 'Operations with radicals', 'Add and subtract like radicals, multiply radical expressions with the distributive property, and rationalize binomial denominators with conjugates.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_59ba4247d4ca45', 'les_00ede0b35eda6d', 1, 'Add and subtract radicals by simplifying and combining like radicals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dba055c955479f', 'les_00ede0b35eda6d', 2, 'Multiply radical expressions, including binomials, and simplify the results.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_37f345d52d2793', 'les_00ede0b35eda6d', 3, 'Rationalize denominators of the form a + √b using conjugates.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_59ba4247d4ca45', 'les_00ede0b35eda6d', 'learn', 1, 'definition', '{"term":"Like radicals","body":"Radicals with the same index and the same radicand, such as $4\\sqrt{3}$ and $-\\sqrt{3}$. They combine like like terms: $4\\sqrt{3} - \\sqrt{3} = 3\\sqrt{3}$. $\\sqrt{2}$ and $\\sqrt{3}$ are not like radicals and don''t combine."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dba055c955479f', 'les_00ede0b35eda6d', 'learn', 2, 'worked_example', '{"title":"Simplify $\\sqrt{50} + 3\\sqrt{8} - \\sqrt{18}$","steps":[{"latex":"5\\sqrt{2} + 3(2\\sqrt{2}) - 3\\sqrt{2}","explanation":"Simplify each radical first. Hidden like radicals appear."},{"latex":"5\\sqrt{2} + 6\\sqrt{2} - 3\\sqrt{2} = 8\\sqrt{2}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_37f345d52d2793', 'les_00ede0b35eda6d', 'learn', 3, 'worked_example', '{"title":"Multiply $\\sqrt{6} \\cdot \\sqrt{15}$ and $2\\sqrt{3}(4 - \\sqrt{3})$","steps":[{"latex":"\\sqrt{90} = \\sqrt{9 \\cdot 10} = 3\\sqrt{10}","explanation":"Product property, then simplify."},{"latex":"8\\sqrt{3} - 2(\\sqrt{3})^2 = 8\\sqrt{3} - 6","explanation":"Distribute; $(\\sqrt{3})^2 = 3$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0356b02d45c737', 'les_00ede0b35eda6d', 'learn', 4, 'worked_example', '{"title":"Multiply $(3 + \\sqrt{5})(2 - \\sqrt{5})$","steps":[{"latex":"6 - 3\\sqrt{5} + 2\\sqrt{5} - 5","explanation":"Four products, as with any two binomials."},{"latex":"1 - \\sqrt{5}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2640bd5ae9a6dd', 'les_00ede0b35eda6d', 'learn', 5, 'definition', '{"term":"Conjugates","body":"$a + \\sqrt{b}$ and $a - \\sqrt{b}$ are conjugates. Their product is rational: $(a + \\sqrt{b})(a - \\sqrt{b}) = a^2 - b$, a difference of squares."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dd6fd34b7fcbdf', 'les_00ede0b35eda6d', 'learn', 6, 'worked_example', '{"title":"Rationalize $\\dfrac{4}{3 - \\sqrt{5}}$","steps":[{"latex":"\\frac{4}{3 - \\sqrt{5}} \\cdot \\frac{3 + \\sqrt{5}}{3 + \\sqrt{5}}","explanation":"Multiply by the conjugate over itself."},{"latex":"\\frac{4(3 + \\sqrt{5})}{9 - 5} = \\frac{4(3 + \\sqrt{5})}{4}","explanation":"The denominator becomes 9 − 5 = 4."},{"latex":"3 + \\sqrt{5}","explanation":""}],"check":"Check: $\\frac{4}{3 - 2.236} \\approx 5.236$ and $3 + 2.236 = 5.236$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3df5627c60c079', 'les_00ede0b35eda6d', 'learn', 7, 'callout', '{"tone":"warning","title":"Squaring a binomial with a radical","body":"$(1 + \\sqrt{2})^2 \\ne 1 + 2$. It''s $1 + 2\\sqrt{2} + 2 = 3 + 2\\sqrt{2}$: don''t forget the middle term."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a0ea59f9dfe14c', 'les_00ede0b35eda6d', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Exact lengths from the Pythagorean theorem often need radical arithmetic: the perimeter of a right triangle with legs 1 and 2 is $3 + \\sqrt{5}$. Conjugates reappear when dividing complex numbers in Algebra 2."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_59ba4247d4ca45', 'les_00ede0b35eda6d', 1, 'practice', 'short_text', 1, 'Simplify $7\sqrt{3} - 2\sqrt{3}$.', '{"accept":["5sqrt(3)","5√3","5sqrt3"]}', '["Like radicals combine."]', '$5\sqrt{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dba055c955479f', 'les_00ede0b35eda6d', 2, 'practice', 'short_text', 2, 'Simplify $\sqrt{12} + \sqrt{27}$.', '{"accept":["5sqrt(3)","5√3","5sqrt3"]}', '["$\\sqrt{12} = 2\\sqrt{3}$ and $\\sqrt{27} = 3\\sqrt{3}$."]', '$5\sqrt{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_37f345d52d2793', 'les_00ede0b35eda6d', 3, 'practice', 'short_text', 2, 'Multiply $\sqrt{10} \cdot \sqrt{14}$ and simplify.', '{"accept":["2sqrt(35)","2√35","2sqrt35"]}', '["$\\sqrt{140} = \\sqrt{4 \\cdot 35}$."]', '$2\sqrt{35}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0356b02d45c737', 'les_00ede0b35eda6d', 4, 'practice', 'short_text', 2, 'Multiply $(4 + \sqrt{3})(4 - \sqrt{3})$.', '{"accept":["13"]}', '["Conjugates: a² − b."]', '$16 - 3 = 13$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2640bd5ae9a6dd', 'les_00ede0b35eda6d', 5, 'practice', 'short_text', 3, 'Expand $(2 + \sqrt{7})^2$. Use the format 11+4sqrt(7).', '{"accept":["11+4sqrt(7)","11+4√7","11+4sqrt7"]}', '["$4 + 4\\sqrt{7} + 7$."]', '$11 + 4\sqrt{7}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dd6fd34b7fcbdf', 'les_00ede0b35eda6d', 6, 'review', 'short_text', 3, 'Rationalize $\dfrac{2}{\sqrt{3} + 1}$. Use the format sqrt(3)-1.', '{"accept":["sqrt(3)-1","√3-1","sqrt3-1","-1+sqrt(3)"]}', '["Multiply by the conjugate √3 − 1.","The denominator becomes 3 − 1 = 2."]', '$\frac{2(\sqrt{3} - 1)}{2} = \sqrt{3} - 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3df5627c60c079', 'les_00ede0b35eda6d', 7, 'review', 'multiple_choice', 2, 'Which pair are like radicals?', '{"choices":["$\\sqrt{8}$ and $\\sqrt{2}$","$\\sqrt{3}$ and $\\sqrt[3]{3}$","$2\\sqrt{5}$ and $5\\sqrt{2}$","$\\sqrt{6}$ and $\\sqrt{3}$"],"answer":0}', '["Simplify first."]', '$\sqrt{8} = 2\sqrt{2}$, so it is a like radical with $\sqrt{2}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_76935b8870cd26', 'subj_math', 'radicals', 'Radicals', 'Expressions with roots, such as √x and ∛x.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_00ede0b35eda6d', (SELECT id FROM concepts WHERE slug = 'radicals'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_00ede0b35eda6d', (SELECT id FROM concepts WHERE slug = 'special-products'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_00ede0b35eda6d', (SELECT id FROM formulas WHERE slug = 'special-products'), 1);

-- Lesson: piecewise-step-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_681187eb4b7a90', 'piecewise-step-functions', 'Piecewise and step functions', 'Evaluate, graph and write piecewise-defined functions, including absolute value as a piecewise function and step functions such as the floor function and postage rates.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_336b653c8b6456', 'les_681187eb4b7a90', 1, 'Evaluate a piecewise function by choosing the correct rule for each input.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_48ace5ef3d4133', 'les_681187eb4b7a90', 2, 'Graph piecewise functions with correct open and closed endpoints.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bdcc1c2e35312d', 'les_681187eb4b7a90', 3, 'Write piecewise and step functions that model real situations.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_336b653c8b6456', 'les_681187eb4b7a90', 'learn', 1, 'definition', '{"term":"Piecewise function","body":"A function that uses different rules on different intervals of its domain, for example $f(x) = \\begin{cases} x + 2, & x < 1 \\\\ 4 - x, & x \\ge 1 \\end{cases}$. The intervals must not overlap, so each input still has exactly one output."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_48ace5ef3d4133', 'les_681187eb4b7a90', 'learn', 2, 'worked_example', '{"title":"Evaluate $f(-3)$, $f(1)$ and $f(5)$ for the function above","steps":[{"latex":"f(-3) = -3 + 2 = -1","explanation":"−3 < 1: use the first rule."},{"latex":"f(1) = 4 - 1 = 3","explanation":"1 ≥ 1: use the second rule."},{"latex":"f(5) = 4 - 5 = -1","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bdcc1c2e35312d', 'les_681187eb4b7a90', 'learn', 3, 'text', '{"body":"To graph, draw each rule only over its own interval. At a boundary, use a closed dot if the endpoint belongs to that piece and an open dot if it does not. Here the first piece approaches $(1, 3)$ with an open dot, and the second piece starts at $(1, 3)$ with a closed dot. The two pieces happen to meet, so the graph has no break."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9a413bbd5388e9', 'les_681187eb4b7a90', 'learn', 4, 'callout', '{"tone":"note","title":"Absolute value is piecewise","body":"$|x| = \\begin{cases} -x, & x < 0 \\\\ x, & x \\ge 0 \\end{cases}$. That explains its V shape: two rays with slopes $-1$ and $1$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5aaa8712bde672', 'les_681187eb4b7a90', 'learn', 5, 'definition', '{"term":"Step function","body":"A piecewise function that is constant on each interval, so its graph looks like stairs. The greatest-integer (floor) function $\\lfloor x \\rfloor$ gives the greatest integer less than or equal to $x$: $\\lfloor 3.7 \\rfloor = 3$, $\\lfloor -1.2 \\rfloor = -2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fc794851b761e4', 'les_681187eb4b7a90', 'learn', 6, 'worked_example', '{"title":"Parking costs 4 dollars for the first hour or less, plus 3 dollars for each additional hour or part of an hour, up to 16 dollars a day","steps":[{"latex":"0 < t \\le 1: C = 4","explanation":""},{"latex":"1 < t \\le 2: C = 7,\\quad 2 < t \\le 3: C = 10","explanation":"Each new partial hour adds 3 dollars."},{"latex":"C(2.25) = 10","explanation":"2 hours 15 minutes is in the third hour."},{"latex":"3 < t \\le 4: C = 13;\\quad t > 4: C = 16","explanation":"The 5th hour brings the charge to 16 dollars, the daily maximum, so it never goes higher."}],"check":"On a graph, each step has an open dot on the left and a closed dot on the right."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bc82b1384424bd', 'les_681187eb4b7a90', 'learn', 7, 'callout', '{"tone":"warning","title":"Check the boundary","body":"Most errors happen exactly at the boundary. For $x = 1$ above, read the conditions carefully: $x < 1$ excludes 1, and $x \\ge 1$ includes it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_feef8225dc71f2', 'les_681187eb4b7a90', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Tax brackets, shipping rates, phone plans with data caps, and overtime pay (regular rate up to 40 hours, 1.5 times after) are all piecewise functions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_336b653c8b6456', 'les_681187eb4b7a90', 1, 'practice', 'numeric', 1, 'For $g(x) = \begin{cases} 2x, & x \le 3 \\ x + 10, & x > 3 \end{cases}$, find $g(3)$.', '{"answer":6}', '["3 ≤ 3, so use the first rule."]', '$g(3) = 2(3) = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_48ace5ef3d4133', 'les_681187eb4b7a90', 2, 'practice', 'numeric', 1, 'For the same $g$, find $g(4)$.', '{"answer":14}', '["4 > 3."]', '$g(4) = 4 + 10 = 14$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bdcc1c2e35312d', 'les_681187eb4b7a90', 3, 'practice', 'numeric', 2, 'Evaluate $\lfloor -2.5 \rfloor$.', '{"answer":-3}', '["The greatest integer less than or equal to −2.5."]', 'On the number line, the integers below $-2.5$ are $-3, -4, \dots$; the greatest is $-3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9a413bbd5388e9', 'les_681187eb4b7a90', 4, 'practice', 'multiple_choice', 2, 'For $h(x) = \begin{cases} x^2, & x < 0 \\ 5, & 0 \le x < 2 \\ 7 - x, & x \ge 2 \end{cases}$, what is $h(2)$?', '{"choices":["4","5","7","9"],"answer":1}', '["Which interval contains 2?"]', '$2 \ge 2$, so $h(2) = 7 - 2 = 5$. (It happens to match the middle piece''s value, but the third rule applies.)');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5aaa8712bde672', 'les_681187eb4b7a90', 5, 'practice', 'numeric', 2, 'A worker earns 18 dollars per hour for the first 40 hours and 27 dollars per hour after that. What does she earn for 46 hours?', '{"answer":882,"unit":"dollars"}', '["$40 \\cdot 18 + 6 \\cdot 27$."]', '$720 + 162 = 882$ dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fc794851b761e4', 'les_681187eb4b7a90', 6, 'review', 'numeric', 3, 'Using the parking rates in the lesson, how much does it cost to park for 3 hours 40 minutes?', '{"answer":13,"unit":"dollars"}', '["3 hours 40 minutes is in the 4th hour."]', '$4 + 3 \cdot 3 = 13$ dollars.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bc82b1384424bd', 'les_681187eb4b7a90', 7, 'review', 'short_text', 3, 'Write $f(x) = |x - 2|$ as a piecewise function. Enter the rule for $x < 2$ in the form y=….', '{"accept":["y=2-x","y=-x+2","y=-(x-2)"]}', '["For x < 2, x − 2 is negative."]', 'For $x < 2$, $|x - 2| = -(x - 2) = 2 - x$; for $x \ge 2$, it is $x - 2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_ac4aceeeb29670', 'subj_math', 'piecewise-functions', 'Piecewise functions', 'Functions defined by different rules on different parts of their domain.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_681187eb4b7a90', (SELECT id FROM concepts WHERE slug = 'piecewise-functions'));

-- Lesson: proof-with-properties
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_dbfccffd6861a4', 'proof-with-properties', 'Proof with the properties of real numbers', 'Write short algebraic proofs, justifying every step with a property, and prove general facts about even and odd integers and simple identities.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_69455f00b7e622', 'les_dbfccffd6861a4', 1, 'Justify each step of solving an equation with a property of equality or of real numbers.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d6e458cb1af1bd', 'les_dbfccffd6861a4', 2, 'Prove simple identities and facts about integers, such as ''the sum of two odd numbers is even''.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f344bb16631c5b', 'les_dbfccffd6861a4', 3, 'Distinguish a proof from checking examples, and use a counterexample to disprove a claim.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_69455f00b7e622', 'les_dbfccffd6861a4', 'learn', 1, 'text', '{"body":"Checking that a statement works for 5 or 50 examples shows it''s plausible, not that it''s always true. A proof shows it holds for every possible value by using only steps that are guaranteed: definitions, the properties of equality and the properties of real numbers."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d6e458cb1af1bd', 'les_dbfccffd6861a4', 'learn', 2, 'worked_example', '{"title":"Prove that if $3(x - 4) = 2x + 1$, then $x = 13$","steps":[{"latex":"3x - 12 = 2x + 1","explanation":"Distributive property."},{"latex":"3x - 12 - 2x = 2x + 1 - 2x","explanation":"Subtraction property of equality."},{"latex":"x - 12 = 1","explanation":"Combine like terms (distributive property) and additive inverse/identity."},{"latex":"x = 13","explanation":"Addition property of equality."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f344bb16631c5b', 'les_dbfccffd6861a4', 'learn', 3, 'definition', '{"term":"Even and odd integers","body":"An integer is even if it equals $2k$ for some integer $k$, and odd if it equals $2k + 1$ for some integer $k$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_06daf5a69252e2', 'les_dbfccffd6861a4', 'learn', 4, 'worked_example', '{"title":"Prove: the sum of any two odd integers is even","steps":[{"latex":"a = 2m + 1,\\ b = 2n + 1","explanation":"Let a and b be any odd integers (m and n are integers). Use different letters: the numbers needn''t be equal."},{"latex":"a + b = 2m + 2n + 2","explanation":"Add and rearrange (commutative and associative properties)."},{"latex":"= 2(m + n + 1)","explanation":"Distributive property."},{"latex":"m + n + 1 \\text{ is an integer}","explanation":"Integers are closed under addition, so a + b is 2 times an integer: even. ∎"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a80ad33ffc0ed8', 'les_dbfccffd6861a4', 'learn', 5, 'worked_example', '{"title":"Prove the identity $(a + b)^2 - (a - b)^2 = 4ab$","steps":[{"latex":"(a^2 + 2ab + b^2) - (a^2 - 2ab + b^2)","explanation":"Expand both squares (distributive property)."},{"latex":"a^2 + 2ab + b^2 - a^2 + 2ab - b^2","explanation":"Distribute the subtraction."},{"latex":"4ab","explanation":"Combine like terms. ∎"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e7ba7537bf131e', 'les_dbfccffd6861a4', 'learn', 6, 'callout', '{"tone":"warning","title":"Examples aren''t proof, but one counterexample is enough","body":"\"$n^2 + n + 41$ is always prime\" holds for $n = 0, 1, \\dots, 39$, but at $n = 40$ it equals $41^2$. To disprove a general claim, a single counterexample suffices."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1120da48f68753', 'les_dbfccffd6861a4', 'learn', 7, 'callout', '{"tone":"tip","title":"Write proofs in two columns","body":"List each statement on the left and its reason on the right. Each reason should be a definition, a given, a property, or a previously proved fact."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2890adeabdc241', 'les_dbfccffd6861a4', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Proof is how mathematics guarantees its results; it also underpins computer science (proving an algorithm always works) and cryptography, whose security rests on proved facts about integers."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_69455f00b7e622', 'les_dbfccffd6861a4', 1, 'practice', 'multiple_choice', 1, 'Which property justifies going from $x + 7 = 12$ to $x = 5$?', '{"choices":["Addition property of equality","Subtraction property of equality","Distributive property","Commutative property"],"answer":1}', '["What was done to both sides?"]', '7 was subtracted from both sides.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d6e458cb1af1bd', 'les_dbfccffd6861a4', 2, 'practice', 'multiple_choice', 2, 'To prove "the product of two even integers is even," how should the integers be written?', '{"choices":["$2k$ and $2k$","$2m$ and $2n$ for integers m, n","$k$ and $k + 2$","$2$ and $4$"],"answer":1}', '["The two even numbers needn''t be equal."]', 'Use $2m$ and $2n$. Then the product is $4mn = 2(2mn)$, which is even.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f344bb16631c5b', 'les_dbfccffd6861a4', 3, 'practice', 'multiple_choice', 2, 'What does $(2m + 1)(2n + 1)$ simplify to, showing that the product of two odd numbers is odd?', '{"choices":["$2(2mn + m + n) + 1$","$4mn + 1$","$2(mn) + 2$","$4mn + 2m + 2n$"],"answer":0}', '["Expand: 4mn + 2m + 2n + 1."]', '$4mn + 2m + 2n + 1 = 2(2mn + m + n) + 1$, which is odd.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_06daf5a69252e2', 'les_dbfccffd6861a4', 4, 'practice', 'short_text', 2, 'Give a counterexample to "the sum of two prime numbers is always even." Enter the two primes separated by a comma, smaller first.', '{"accept":["2,3","2,5","2,7","2,11","2,13"]}', '["Which prime is even?"]', '$2 + 3 = 5$ is odd. Any sum of 2 and an odd prime is a counterexample.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a80ad33ffc0ed8', 'les_dbfccffd6861a4', 5, 'review', 'multiple_choice', 3, 'A student "proves" $a = b$ like this: $a^2 = ab \Rightarrow a^2 - b^2 = ab - b^2 \Rightarrow (a + b)(a - b) = b(a - b) \Rightarrow a + b = b$. Which step is invalid when a = b?', '{"choices":["Subtracting b²","Factoring","Dividing both sides by (a − b)","Writing a² = ab"],"answer":2}', '["What is a − b if a = b?"]', 'If $a = b$, then $a - b = 0$, and dividing by zero is not allowed. That step is invalid.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e7ba7537bf131e', 'les_dbfccffd6861a4', 6, 'review', 'short_text', 3, 'Simplify to prove the identity: $(x + 3)^2 - (x - 3)^2 = ?$ Enter the simplified expression.', '{"accept":["12x"]}', '["Use $(a + b)^2 - (a - b)^2 = 4ab$."]', '$4 \cdot x \cdot 3 = 12x$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_dbfccffd6861a4', (SELECT id FROM concepts WHERE slug = 'field-properties'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0c99c7b4199c45', 'subj_math', 'algebraic-proof', 'Algebraic proof', 'A sequence of justified steps showing a statement holds for all values.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_dbfccffd6861a4', (SELECT id FROM concepts WHERE slug = 'algebraic-proof'));

-- Lesson: reasoning-solution-sets
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5ac84e35a89ed8', 'reasoning-solution-sets', 'Reasoning about solution sets', 'Analyze equations and inequalities with parameters, decide when they have one, none or infinitely many solutions, and describe solution sets precisely in set-builder and interval notation.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a4feffc41dcd57', 'les_5ac84e35a89ed8', 1, 'Classify linear equations as having one solution, no solution, or infinitely many solutions, including equations with parameters.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4d0298075637e5', 'les_5ac84e35a89ed8', 2, 'Find parameter values that produce a given number of solutions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_71bdcc79231f25', 'les_5ac84e35a89ed8', 3, 'Describe solution sets with set-builder notation, interval notation and unions or intersections.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a4feffc41dcd57', 'les_5ac84e35a89ed8', 'learn', 1, 'text', '{"body":"Every linear equation in one variable can be rearranged to the form $ax = b$. Then there are exactly three possibilities: if $a \\ne 0$, there''s one solution $x = \\frac{b}{a}$; if $a = 0$ and $b = 0$, the equation is $0 = 0$ and every real number works; if $a = 0$ and $b \\ne 0$, it''s a false statement with no solution."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4d0298075637e5', 'les_5ac84e35a89ed8', 'learn', 2, 'definition', '{"term":"Set-builder notation","body":"$\\{x \\mid x > 3\\}$ reads \"the set of all $x$ such that $x > 3$.\" The empty set is $\\varnothing$, and all real numbers is $\\mathbb{R}$ or $(-\\infty, \\infty)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_71bdcc79231f25', 'les_5ac84e35a89ed8', 'learn', 3, 'worked_example', '{"title":"For which values of $k$ does $kx + 4 = 3x + 4$ have exactly one solution?","steps":[{"latex":"kx - 3x = 0 \\Rightarrow (k - 3)x = 0","explanation":"Collect x-terms and factor."},{"latex":"k \\ne 3: x = 0","explanation":"One solution."},{"latex":"k = 3: 0 = 0","explanation":"Every real number is a solution."}],"check":"So exactly one solution for every k except 3. No value of k gives no solution here."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8fd3f77f73b0f0', 'les_5ac84e35a89ed8', 'learn', 4, 'worked_example', '{"title":"Find $a$ and $b$ so that $2(x + a) = bx - 6$ has infinitely many solutions","steps":[{"latex":"2x + 2a = bx - 6","explanation":""},{"latex":"b = 2 \\text{ and } 2a = -6","explanation":"The x-coefficients and the constants must both match."},{"latex":"a = -3,\\ b = 2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1467452d384b79', 'les_5ac84e35a89ed8', 'learn', 5, 'worked_example', '{"title":"Describe the solution set of $|x - 1| \\ge 4$ in three ways","steps":[{"latex":"x \\le -3 \\text{ or } x \\ge 5","explanation":"Inequality notation."},{"latex":"\\{x \\mid x \\le -3 \\text{ or } x \\ge 5\\}","explanation":"Set-builder notation."},{"latex":"(-\\infty, -3] \\cup [5, \\infty)","explanation":"Interval notation."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_da8d592c7181f7', 'les_5ac84e35a89ed8', 'experiment', 6, 'activity', '{"activity":"inequality-line","title":"Union of two rays","params":{"rel":"≤","c":-3,"mode":"or","rel2":"≥","c2":5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fcaa16f3732c76', 'les_5ac84e35a89ed8', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"Switch to \"And.\" With these boundaries the solution set is empty. Change the boundaries so \"and\" gives a single point. Which relations make that possible?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3c23f89a36115e', 'les_5ac84e35a89ed8', 'learn', 8, 'callout', '{"tone":"warning","title":"Solving can create or lose solutions","body":"Multiplying both sides by an expression that might be 0, or dividing by one, can change the solution set. That''s why you check solutions and track restrictions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f855cd9d40ae8b', 'les_5ac84e35a89ed8', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers specify tolerances as solution sets, programmers write input validation as unions and intersections of intervals, and the \"no solution / infinitely many\" analysis returns in systems of equations and matrices."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a4feffc41dcd57', 'les_5ac84e35a89ed8', 1, 'practice', 'multiple_choice', 1, 'How many solutions does $5(x - 2) = 5x - 10$ have?', '{"choices":["None","One","Infinitely many","Two"],"answer":2}', '["Simplify both sides."]', 'Both sides are $5x - 10$, so every real number works.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4d0298075637e5', 'les_5ac84e35a89ed8', 2, 'practice', 'multiple_choice', 2, 'How many solutions does $4x + 7 = 2(2x + 3)$ have?', '{"choices":["None","One","Infinitely many","Two"],"answer":0}', '["Simplify the right side."]', '$4x + 7 = 4x + 6$ gives $7 = 6$, which is false: no solution.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_71bdcc79231f25', 'les_5ac84e35a89ed8', 3, 'practice', 'short_text', 2, 'For what value of $k$ does $kx - 5 = 2x + 1$ have no solution?', '{"accept":["2","k=2"]}', '["Collect x-terms: (k − 2)x = 6."]', 'If $k = 2$, the equation becomes $0 = 6$, which has no solution.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8fd3f77f73b0f0', 'les_5ac84e35a89ed8', 4, 'practice', 'short_text', 3, 'Find $c$ so that $3(x - 2) + c = 3x + 4$ has infinitely many solutions.', '{"accept":["10","c=10"]}', '["$3x - 6 + c = 3x + 4$."]', '$-6 + c = 4$, so $c = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1467452d384b79', 'les_5ac84e35a89ed8', 5, 'practice', 'multiple_choice', 2, 'Which is the interval notation for $\{x \mid -2 < x \le 7\}$?', '{"choices":["$[-2, 7)$","$(-2, 7]$","$(-2, 7)$","$[-2, 7]$"],"answer":1}', '["Which endpoint is included?"]', '$(-2, 7]$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_da8d592c7181f7', 'les_5ac84e35a89ed8', 6, 'review', 'multiple_choice', 3, 'What is the solution set of $x > 4$ and $x < 4$?', '{"choices":["$\\{4\\}$","$\\varnothing$","$\\mathbb{R}$","$(-\\infty, 4) \\cup (4, \\infty)$"],"answer":1}', '["Can a number be both greater and less than 4?"]', 'No number satisfies both, so the set is empty. (With "or," the answer would be every real number except 4.)');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fcaa16f3732c76', 'les_5ac84e35a89ed8', 7, 'review', 'short_text', 3, 'For which value of $m$ does $mx + 3 \ge mx + 1$ hold? Answer "all" if it holds for every real m, or give the value.', '{"accept":["all"]}', '["Subtract $mx$ from both sides."]', 'It reduces to $3 \ge 1$, which is always true, for every $m$ and every $x$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_61cc25af3ca9f7', 'subj_math', 'solution-sets', 'Solution sets', 'The set of all values that make an equation or inequality true.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5ac84e35a89ed8', (SELECT id FROM concepts WHERE slug = 'solution-sets'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5ac84e35a89ed8', (SELECT id FROM concepts WHERE slug = 'interval-notation'));

-- Lesson: simplifying-radicals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e642620d9fbcce', 'simplifying-radicals', 'Simplifying radical expressions', 'Simplify square and cube roots using perfect-square and perfect-cube factors, simplify radicals with variables, and rationalize denominators.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b66fd88400b6ee', 'les_e642620d9fbcce', 1, 'Use the product and quotient properties of radicals to simplify square roots and cube roots.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7e8d420f01b7ea', 'les_e642620d9fbcce', 2, 'Simplify radicals containing variables, assuming variables are nonnegative.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_408c9261d246b1', 'les_e642620d9fbcce', 3, 'Rationalize a denominator containing a single square root.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b66fd88400b6ee', 'les_e642620d9fbcce', 'learn', 1, 'definition', '{"term":"Product and quotient properties","body":"For $a, b \\ge 0$: $\\sqrt{ab} = \\sqrt{a}\\sqrt{b}$, and for $b > 0$: $\\sqrt{\\dfrac{a}{b}} = \\dfrac{\\sqrt{a}}{\\sqrt{b}}$. The same properties hold for cube roots, with no sign restriction."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7e8d420f01b7ea', 'les_e642620d9fbcce', 'learn', 2, 'text', '{"body":"A square root is in simplest form when the radicand has no perfect-square factor other than 1, there is no fraction under the root, and no root is left in a denominator. To simplify, find the largest perfect-square factor and take its root out."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_408c9261d246b1', 'les_e642620d9fbcce', 'learn', 3, 'worked_example', '{"title":"Simplify $\\sqrt{72}$","steps":[{"latex":"\\sqrt{36 \\cdot 2}","explanation":"36 is the largest perfect square that divides 72."},{"latex":"\\sqrt{36}\\sqrt{2} = 6\\sqrt{2}","explanation":""}],"check":"Check: $6\\sqrt{2} \\approx 6(1.414) = 8.485$ and $\\sqrt{72} \\approx 8.485$. ✓ Using $\\sqrt{4 \\cdot 18} = 2\\sqrt{18}$ first also works, but needs a second step."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_605797e685f828', 'les_e642620d9fbcce', 'learn', 4, 'worked_example', '{"title":"Simplify $\\sqrt[3]{54}$ and $\\sqrt{50x^3y^4}$ ($x, y \\ge 0$)","steps":[{"latex":"\\sqrt[3]{27 \\cdot 2} = 3\\sqrt[3]{2}","explanation":"27 is a perfect cube."},{"latex":"\\sqrt{25 \\cdot 2 \\cdot x^2 \\cdot x \\cdot y^4}","explanation":"Split into squares and leftovers."},{"latex":"5xy^2\\sqrt{2x}","explanation":"$\\sqrt{x^2} = x$ and $\\sqrt{y^4} = y^2$ for nonnegative values."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9a4d5908c516a1', 'les_e642620d9fbcce', 'learn', 5, 'definition', '{"term":"Rationalizing the denominator","body":"Multiply the numerator and denominator by the radical in the denominator, which multiplies the fraction by 1: $\\dfrac{a}{\\sqrt{b}} = \\dfrac{a\\sqrt{b}}{b}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_523e90fc30ae94', 'les_e642620d9fbcce', 'learn', 6, 'worked_example', '{"title":"Rationalize $\\dfrac{6}{\\sqrt{3}}$ and simplify $\\sqrt{\\dfrac{5}{8}}$","steps":[{"latex":"\\frac{6}{\\sqrt{3}} \\cdot \\frac{\\sqrt{3}}{\\sqrt{3}} = \\frac{6\\sqrt{3}}{3} = 2\\sqrt{3}","explanation":""},{"latex":"\\sqrt{\\tfrac{5}{8}} = \\frac{\\sqrt{5}}{2\\sqrt{2}} \\cdot \\frac{\\sqrt{2}}{\\sqrt{2}} = \\frac{\\sqrt{10}}{4}","explanation":"$\\sqrt{8} = 2\\sqrt{2}$."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6c6720480bc908', 'les_e642620d9fbcce', 'learn', 7, 'callout', '{"tone":"warning","title":"Roots don''t split over sums","body":"$\\sqrt{9 + 16} = \\sqrt{25} = 5$, but $\\sqrt{9} + \\sqrt{16} = 7$. The product property works for multiplication, never for addition."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e1becafeba9562', 'les_e642620d9fbcce', 'learn', 8, 'callout', '{"tone":"note","title":"Why absolute value sometimes appears","body":"$\\sqrt{x^2} = |x|$ for any real $x$; for example $\\sqrt{(-3)^2} = 3$. That''s why problems often say \"assume all variables are nonnegative.\""}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0842439540de53', 'les_e642620d9fbcce', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Exact answers in geometry are often radicals: a square with side 5 has diagonal $5\\sqrt{2}$, and an equilateral triangle with side 6 has height $3\\sqrt{3}$. Simplified radicals make such answers comparable and easy to estimate."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b66fd88400b6ee', 'les_e642620d9fbcce', 1, 'practice', 'short_text', 1, 'Simplify $\sqrt{48}$. Use the format 4sqrt(3).', '{"accept":["4sqrt(3)","4√3","4sqrt3"]}', '["48 = 16 · 3."]', '$4\sqrt{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7e8d420f01b7ea', 'les_e642620d9fbcce', 2, 'practice', 'short_text', 2, 'Simplify $\sqrt{180}$.', '{"accept":["6sqrt(5)","6√5","6sqrt5"]}', '["180 = 36 · 5."]', '$6\sqrt{5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_408c9261d246b1', 'les_e642620d9fbcce', 3, 'practice', 'short_text', 2, 'Simplify $\sqrt[3]{-40}$.', '{"accept":["-2cbrt(5)","-2∛5","-2*cbrt(5)"]}', '["−40 = −8 · 5.","Use the format -2cbrt(5)."]', '$\sqrt[3]{-8}\sqrt[3]{5} = -2\sqrt[3]{5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_605797e685f828', 'les_e642620d9fbcce', 4, 'practice', 'short_text', 2, 'Rationalize $\dfrac{10}{\sqrt{5}}$. Use the format 2sqrt(5).', '{"accept":["2sqrt(5)","2√5","2sqrt5"]}', '["Multiply by $\\frac{\\sqrt{5}}{\\sqrt{5}}$."]', '$\frac{10\sqrt{5}}{5} = 2\sqrt{5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9a4d5908c516a1', 'les_e642620d9fbcce', 5, 'practice', 'short_text', 3, 'Simplify $\sqrt{98a^5b^2}$ for $a, b \ge 0$. Use the format 7a^2bsqrt(2a).', '{"accept":["7a^2bsqrt(2a)","7a^2b√(2a)","7a^2b√2a"]}', '["98 = 49 · 2 and a⁵ = a⁴ · a."]', '$7a^2b\sqrt{2a}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_523e90fc30ae94', 'les_e642620d9fbcce', 6, 'practice', 'multiple_choice', 2, 'Which is NOT in simplest form?', '{"choices":["$3\\sqrt{7}$","$\\sqrt{30}$","$2\\sqrt{12}$","$\\frac{\\sqrt{6}}{3}$"],"answer":2}', '["Look for a perfect-square factor under a root."]', '$\sqrt{12} = 2\sqrt{3}$, so $2\sqrt{12} = 4\sqrt{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6c6720480bc908', 'les_e642620d9fbcce', 7, 'review', 'numeric', 3, 'A square has area 75 cm². Its side is $a\sqrt{3}$ cm. Find $a$.', '{"answer":5}', '["$\\sqrt{75} = \\sqrt{25 \\cdot 3}$."]', '$\sqrt{75} = 5\sqrt{3}$, so $a = 5$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_76935b8870cd26', 'subj_math', 'radicals', 'Radicals', 'Expressions with roots, such as √x and ∛x.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e642620d9fbcce', (SELECT id FROM concepts WHERE slug = 'radicals'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e642620d9fbcce', (SELECT id FROM concepts WHERE slug = 'square-roots'));

-- Lesson: square-root-cube-root-functions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_40b5d6e1b02aa7', 'square-root-cube-root-functions', 'Square root and cube root functions', 'Graph f(x) = √x and f(x) = ∛x and their transformations, find domain and range, and compare their shapes and rates of change.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6da615cd95a27f', 'les_40b5d6e1b02aa7', 1, 'Graph the parent functions √x and ∛x from key points and describe their domain, range and shape.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d220528a81a001', 'les_40b5d6e1b02aa7', 2, 'Graph transformations a√(x − h) + k and a∛(x − h) + k and give their domain and range.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3b263727f59a7a', 'les_40b5d6e1b02aa7', 3, 'Solve simple radical equations and check for extraneous solutions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6da615cd95a27f', 'les_40b5d6e1b02aa7', 'learn', 1, 'definition', '{"term":"Square root function","body":"$f(x) = \\sqrt{x}$ has domain $[0, \\infty)$ and range $[0, \\infty)$. Key points: $(0, 0), (1, 1), (4, 2), (9, 3)$. It rises quickly at first, then more and more slowly."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d220528a81a001', 'les_40b5d6e1b02aa7', 'learn', 2, 'definition', '{"term":"Cube root function","body":"$g(x) = \\sqrt[3]{x}$ has domain and range all real numbers. Key points: $(-8, -2), (-1, -1), (0, 0), (1, 1), (8, 2)$. It is symmetric about the origin."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3b263727f59a7a', 'les_40b5d6e1b02aa7', 'learn', 3, 'text', '{"body":"These are inverses of $y = x^2$ (for $x \\ge 0$) and $y = x^3$: swap the coordinates of the key points of the square and cube functions and you get these graphs. That''s why $\\sqrt{x}$ looks like half of a sideways parabola."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5a2a33cc314e6e', 'les_40b5d6e1b02aa7', 'learn', 4, 'worked_example', '{"title":"Graph $y = -2\\sqrt{x - 3} + 1$ and give its domain and range","steps":[{"latex":"(3, 1)","explanation":"The starting point moves from (0, 0) to (h, k) = (3, 1)."},{"latex":"(4, -1),\\ (7, -3),\\ (12, -5)","explanation":"From (1, 1), (4, 2), (9, 3): shift right 3, multiply y by −2, then add 1."},{"latex":"D = [3, \\infty),\\ R = (-\\infty, 1]","explanation":"The reflection makes the graph go down from its start."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2631f08eb4b86b', 'les_40b5d6e1b02aa7', 'learn', 5, 'worked_example', '{"title":"Give the domain and key points of $y = \\sqrt[3]{x + 1} - 2$","steps":[{"latex":"D = R = (-\\infty, \\infty)","explanation":"Cube roots accept every real input."},{"latex":"(-1, -2)","explanation":"The center point (0, 0) moves left 1 and down 2."},{"latex":"(-9, -4),\\ (0, -1),\\ (7, 0)","explanation":"Shift (−8, −2), (1, 1), (8, 2) the same way."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_da453b064cf2cd', 'les_40b5d6e1b02aa7', 'learn', 6, 'worked_example', '{"title":"Solve $\\sqrt{2x + 3} = x$","steps":[{"latex":"2x + 3 = x^2","explanation":"Square both sides."},{"latex":"x^2 - 2x - 3 = 0 \\Rightarrow x = 3 \\text{ or } x = -1","explanation":""},{"latex":"x = 3: \\sqrt{9} = 3 ✓ \\quad x = -1: \\sqrt{1} = 1 \\ne -1","explanation":"Check both."},{"latex":"x = 3","explanation":"x = −1 is extraneous: it was introduced by squaring."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_91d2a4ba6bd3b7', 'les_40b5d6e1b02aa7', 'learn', 7, 'callout', '{"tone":"warning","title":"Always check radical equations","body":"Squaring both sides can create solutions that don''t satisfy the original equation, because $(-1)^2$ and $1^2$ are equal. Substitute every answer back into the original."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fe23f1e7116591', 'les_40b5d6e1b02aa7', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"The time for a dropped object to fall $d$ meters is $t = \\sqrt{d/4.9}$ seconds, a pendulum''s period grows with $\\sqrt{L}$, and the side of a cube with volume $V$ is $\\sqrt[3]{V}$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6da615cd95a27f', 'les_40b5d6e1b02aa7', 1, 'practice', 'multiple_choice', 1, 'What is the domain of $f(x) = \sqrt{x + 5}$?', '{"choices":["$x \\ge 5$","$x \\ge -5$","All real numbers","$x > 0$"],"answer":1}', '["Require $x + 5 \\ge 0$."]', '$x \ge -5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d220528a81a001', 'les_40b5d6e1b02aa7', 2, 'practice', 'multiple_choice', 1, 'What is the domain of $g(x) = \sqrt[3]{x - 4}$?', '{"choices":["$x \\ge 4$","$x \\ge 0$","All real numbers","$x \\ne 4$"],"answer":2}', '["Cube roots of negatives are real."]', 'All real numbers.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3b263727f59a7a', 'les_40b5d6e1b02aa7', 3, 'practice', 'short_text', 2, 'What is the starting point of $y = \sqrt{x + 2} - 6$? Enter as (x,y).', '{"accept":["(-2,-6)"]}', '["(h, k) with h = −2."]', '$(-2, -6)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5a2a33cc314e6e', 'les_40b5d6e1b02aa7', 4, 'practice', 'multiple_choice', 2, 'What is the range of $y = -\sqrt{x} + 4$?', '{"choices":["$y \\ge 4$","$y \\le 4$","All real numbers","$y \\ge 0$"],"answer":1}', '["The reflection makes the graph go down from (0, 4)."]', '$y \le 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2631f08eb4b86b', 'les_40b5d6e1b02aa7', 5, 'practice', 'numeric', 2, 'Solve $\sqrt{x - 1} = 5$.', '{"answer":26}', '["Square both sides."]', '$x - 1 = 25$, so $x = 26$. Check: $\sqrt{25} = 5$ ✓.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_da453b064cf2cd', 'les_40b5d6e1b02aa7', 6, 'practice', 'numeric', 3, 'Solve $\sqrt{x + 6} = x$. (One solution is extraneous; enter the valid one.)', '{"answer":3}', '["$x^2 - x - 6 = 0$.","Check both candidates."]', '$x = 3$ or $x = -2$. $\sqrt{9} = 3$ ✓, but $\sqrt{4} = 2 \ne -2$, so only $x = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_91d2a4ba6bd3b7', 'les_40b5d6e1b02aa7', 7, 'review', 'numeric', 3, 'How long does it take a stone to fall 44.1 m, using $t = \sqrt{d / 4.9}$?', '{"answer":3,"unit":"s"}', '["$44.1 / 4.9 = 9$."]', '$t = \sqrt{9} = 3$ s.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a1fba3bac364c9', 'subj_math', 'radical-functions', 'Radical functions', 'Functions such as √x and ∛x and their transformations.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_40b5d6e1b02aa7', (SELECT id FROM concepts WHERE slug = 'radical-functions'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d25fe88520a9bc', 'subj_math', 'function-transformations', 'Function transformations', 'Shifting, reflecting and stretching graphs by changing a function''s formula.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_40b5d6e1b02aa7', (SELECT id FROM concepts WHERE slug = 'function-transformations'));

-- Lesson: transformations-linear-absolute-value
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_91c4fe0925d460', 'transformations-linear-absolute-value', 'Transformations of linear and absolute value functions', 'Describe and graph translations, reflections, stretches and compressions of f(x) = x and f(x) = |x|, and write the equation of a transformed graph.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_21fb39988c1269', 'les_91c4fe0925d460', 1, 'Describe how a, h and k change the graph of g(x) = a|x − h| + k relative to f(x) = |x|.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ffa5ddc0e17484', 'les_91c4fe0925d460', 2, 'Graph transformed linear and absolute value functions from their equations.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2d0667ce07dfaf', 'les_91c4fe0925d460', 3, 'Write the equation of a transformed absolute value graph from its vertex and one other point.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_21fb39988c1269', 'les_91c4fe0925d460', 'learn', 1, 'text', '{"body":"The parent function $f(x) = |x|$ is a V with vertex $(0, 0)$ and slopes $\\pm 1$. Every function $g(x) = a|x - h| + k$ is the same V, moved and reshaped. Learning what each parameter does lets you sketch the graph without a table."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ffa5ddc0e17484', 'les_91c4fe0925d460', 'learn', 2, 'definition', '{"term":"Effects of the parameters","body":"$k$: shifts the graph up ($k > 0$) or down. $h$: shifts it right ($h > 0$) or left; note the minus sign in $x - h$. $|a| > 1$: vertical stretch (narrower V); $0 < |a| < 1$: vertical compression (wider V). $a < 0$: reflection over the $x$-axis (upside-down V). The vertex is $(h, k)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2d0667ce07dfaf', 'les_91c4fe0925d460', 'learn', 3, 'worked_example', '{"title":"Describe and graph $g(x) = -2|x + 3| + 4$","steps":[{"latex":"h = -3,\\ k = 4","explanation":"x + 3 = x − (−3): left 3, then up 4. Vertex (−3, 4)."},{"latex":"a = -2","explanation":"Reflected over the x-axis and stretched by 2: slopes −2 and 2 on the two sides."},{"latex":"(-2, 2),\\ (-4, 2)","explanation":"One unit from the vertex, the graph drops 2."}],"check":"Zeros: $-2|x + 3| + 4 = 0$ gives $|x + 3| = 2$, so $x = -1$ or $x = -5$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10c6f3612c730a', 'les_91c4fe0925d460', 'experiment', 4, 'activity', '{"activity":"vertex-explorer","title":"The same parameters on a parabola","params":{"a":-2,"h":-3,"k":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_58f3929507de93', 'les_91c4fe0925d460', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"The parabola $y = -2(x + 3)^2 + 4$ uses the same $a$, $h$ and $k$ as $g$. Drag the vertex: the rules for $h$ and $k$ are identical for every parent function. Now change $a$ by dragging the hollow point. Which way does a negative $a$ flip the graph?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ce32c9ee53d350', 'les_91c4fe0925d460', 'learn', 6, 'text', '{"body":"Linear functions transform the same way. Starting from $f(x) = x$, the function $g(x) = a(x - h) + k$ is a line through $(h, k)$ with slope $a$. That''s point-slope form! For lines, a vertical shift and a horizontal shift can look the same: $y = x + 3$ is both \"up 3\" and \"left 3.\""}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_37d8c65d562ea2', 'les_91c4fe0925d460', 'learn', 7, 'worked_example', '{"title":"Write the absolute value function with vertex $(2, -1)$ through $(4, 5)$","steps":[{"latex":"g(x) = a|x - 2| - 1","explanation":"Use the vertex."},{"latex":"5 = a|4 - 2| - 1 \\Rightarrow 6 = 2a \\Rightarrow a = 3","explanation":"Substitute the point."},{"latex":"g(x) = 3|x - 2| - 1","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_005ff56d96a981', 'les_91c4fe0925d460', 'learn', 8, 'callout', '{"tone":"warning","title":"Inside vs outside","body":"Changes inside the absolute value (to $x$) move the graph horizontally and act opposite to their sign. Changes outside move it vertically and act as written. $|x - 5|$ moves right 5; $|x| - 5$ moves down 5."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4812d8c1f36b82', 'les_91c4fe0925d460', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"A car driving at a steady 60 km/h passes a toll booth at time $t_0$ hours. Its distance from the booth is $d = 60|t - t_0|$ km, a V-shaped graph with its vertex at the moment it passes. Absolute value functions model distances, tolerances and reflections such as light bouncing off a mirror."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_21fb39988c1269', 'les_91c4fe0925d460', 1, 'practice', 'short_text', 1, 'What is the vertex of $g(x) = |x - 4| + 7$? Enter as (x,y).', '{"accept":["(4,7)"]}', '["Vertex is (h, k)."]', '$(4, 7)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ffa5ddc0e17484', 'les_91c4fe0925d460', 2, 'practice', 'multiple_choice', 1, 'How does $g(x) = |x| - 6$ compare with $f(x) = |x|$?', '{"choices":["Left 6","Right 6","Down 6","Up 6"],"answer":2}', '["The change is outside the absolute value."]', 'Subtracting 6 outside shifts the graph down 6.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2d0667ce07dfaf', 'les_91c4fe0925d460', 3, 'practice', 'multiple_choice', 2, 'How does $g(x) = \frac{1}{2}|x + 1|$ compare with $|x|$?', '{"choices":["Right 1 and stretched","Left 1 and compressed vertically","Left 1 and reflected","Up 1 and compressed"],"answer":1}', '["x + 1 = x − (−1).","a = 1/2."]', 'Left 1, with a vertical compression by $\frac{1}{2}$ (wider V).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_10c6f3612c730a', 'les_91c4fe0925d460', 4, 'practice', 'short_text', 2, 'Write the function for $|x|$ reflected over the x-axis, shifted right 3 and up 2. Use the format y=-|x-3|+2.', '{"accept":["y=-|x-3|+2","y=2-|x-3|"]}', '["Reflection: a = −1."]', '$y = -|x - 3| + 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_58f3929507de93', 'les_91c4fe0925d460', 5, 'practice', 'short_text', 3, 'Find the zeros of $g(x) = 2|x - 1| - 6$. Enter both, smaller first.', '{"accept":["-2,4"]}', '["$|x - 1| = 3$."]', '$x - 1 = \pm 3$: $x = -2$ or $x = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ce32c9ee53d350', 'les_91c4fe0925d460', 6, 'review', 'short_text', 3, 'An absolute value graph has vertex $(-1, 3)$ and passes through $(1, -1)$. Find $a$.', '{"accept":["-2","a=-2"]}', '["$-1 = a|1 + 1| + 3$."]', '$-4 = 2a$, so $a = -2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_37d8c65d562ea2', 'les_91c4fe0925d460', 7, 'review', 'multiple_choice', 3, 'The line $y = 2(x - 1) + 5$ is a transformation of $y = x$. Which describes it?', '{"choices":["Slope 2 through (1, 5)","Slope 5 through (1, 2)","Slope 2 through (−1, 5)","Slope 1 through (2, 5)"],"answer":0}', '["Compare with y = a(x − h) + k."]', '$a = 2$ is the slope and $(h, k) = (1, 5)$ is a point on the line.');
